void wait_for_drain_edgeport(struct edgeport_port *port, unsigned long timeout, int flush)
{
    struct tty_struct *tty;
    wait_queue_t wait;
    unsigned long time_limit;
    unsigned int drain_time = 0;
    int disconn = 0;

    if (!port || !port->port)
        return;

    tty = port->port->tty;
    if (!tty)
        return;

    init_waitqueue_entry(&wait, current);

    time_limit = jiffies + timeout;

    add_wait_queue(&tty->write_wait, &wait);

    while (!disconn && time_before(jiffies, time_limit)) {
        set_current_state(TASK_INTERRUPTIBLE);

        if (port->disconnected)
            disconn = 1;

        if (disconn || !tty->chars_in_buffer(tty))
            break;

        spin_unlock(&port->port_lock);
        schedule_timeout(timeout);
        spin_lock(&port->port_lock);
    }

    set_current_state(TASK_RUNNING);
    remove_wait_queue(&tty->write_wait, &wait);

    if (flush)
        tty->flush_chars(tty);

    if (port->baud_rate > 0)
        drain_time = (port->baud_rate / 10);

    if (drain_time > 0)
        schedule_timeout(msecs_to_jiffies(drain_time));
}

void edgeport_drain_data(struct edgeport_port *port, unsigned long timeout, int flush)
{
    struct tty_struct *tty;
    unsigned long orig_jiffies = jiffies;
    unsigned long time_limit;
    int discon;
    DECLARE_WAITQUEUE(wait, current);

    if (!port)
        return;

    tty = port->tty;
    if (!tty)
        return;

    time_limit = jiffies + timeout;

    add_wait_queue(&tty->write_wait, &wait);
    set_current_state(TASK_INTERRUPTIBLE);

    while (1) {
        unsigned long timeout_val;

        spin_lock_irq(&port->lock);
        discon = port->disconnected;
        spin_unlock_irq(&port->lock);

        if (discon)
            break;

        if (time_after(jiffies, time_limit))
            break;

        if (tty_chars_in_buffer(tty) == 0)
            break;

        timeout_val = time_limit - jiffies;
        schedule_timeout(timeout_val);
    }

    set_current_state(TASK_RUNNING);
    remove_wait_queue(&tty->write_wait, &wait);

    if (flush)
        tty_flush(tty, 0);

    timeout = port->baud_rate ? (port->baud_rate + 999999) / 1000000 : 0;
    timeout = max(timeout, 1UL);

    while (1) {
        unsigned long timeout_val;

        spin_lock_irq(&port->lock);
        discon = port->disconnected;
        spin_unlock_irq(&port->lock);

        if (discon)
            break;

        if (time_after(jiffies, time_limit))
            break;

        timeout_val = min(time_limit - jiffies, timeout * 2);
        schedule_timeout(timeout_val);
    }

    tty->low_latency = 0;
}

void edgeport_drain(struct edgeport_port *port, unsigned long timeout, int flush)
{
	struct tty_struct *tty;
	DECLARE_WAIT_QUEUE_HEAD_ONSTACK(wait);
	unsigned long start_jiffies;
	unsigned long baud_rate;
	int disconn;
	int drain_complete = 0;

	if (!port || !port->tport)
		return;

	tty = port->tport->tty;
	if (!tty)
		return;

	start_jiffies = jiffies;
	disconn = 0;

	while (!disconn && !drain_complete && time_before(jiffies, start_jiffies + timeout)) {
		unsigned long flags;

		spin_lock_irqsave(&port->lock, flags);

		if (port->disconnected) {
			disconn = 1;
		} else {
			if (port->tx_bytes == 0)
				drain_complete = 1;
		}

		spin_unlock_irqrestore(&port->lock, flags);

		if (!drain_complete && !disconn)
			schedule_timeout_uninterruptible(1);
	}

	if (flush)
		port->tx_bytes = 0;

	baud_rate = port->baud_rate ?: 9600;
	if (baud_rate > 0)
		schedule_timeout_uninterruptible((208 * HZ) / baud_rate);
}

void edgeport_drain(struct edgeport_port *port, unsigned long timeout, int flush)
{
	struct tty_struct *tty;
	DECLARE_WAIT_QUEUE_HEAD_ONSTACK(wq);
	unsigned long orig_jiffies = jiffies;
	unsigned long time_limit = jiffies + timeout;
	unsigned long flags;
	int draining = 1;

	tty = port->port.tty;
	if (!tty)
		return;

	add_wait_queue(&wq, &current);
	set_current_state(TASK_INTERRUPTIBLE);

	while (draining) {
		if (signal_pending(current))
			break;

		spin_lock_irqsave(&port->lock, flags);
		if (port->disconnected) {
			spin_unlock_irqrestore(&port->lock, flags);
			break;
		}

		if (time_after(jiffies, time_limit))
			break;

		if (port->tx_bytes == 0)
			draining = 0;
		spin_unlock_irqrestore(&port->lock, flags);

		schedule_timeout(1);
	}
	set_current_state(TASK_RUNNING);
	remove_wait_queue(&wq, &current);

	if (flush && tty && tty->driver && tty->driver->flush_buffer)
		tty->driver->flush_buffer(tty);
}

void wait_for_drain_edgeport(struct edgeport_port *port, unsigned long timeout, int flush)
{
    struct tty_struct *tty;
    DECLARE_WAIT_QUEUE_HEAD_ONSTACK(wait);
    unsigned long end_time;
    int disconnecting = 0;
    unsigned int count;
    unsigned int baud_rate;
    long timeout_jiffies;

    if (!port)
        return;

    tty = port->tty;
    if (!tty)
        return;

    end_time = jiffies + timeout;

    spin_lock_irq(&port->lock);
    count = port->xmit_cnt;
    spin_unlock_irq(&port->lock);

    while (count > 0 && time_before(jiffies, end_time)) {
        spin_lock_irq(&port->lock);
        if (port->disconnecting)
            disconnecting = 1;
        spin_unlock_irq(&port->lock);

        if (disconnecting)
            break;

        if (flush) {
            spin_lock_irq(&port->lock);
            port->xmit_cnt = 0;
            spin_unlock_irq(&port->lock);
            break;
        }

        schedule_timeout_uninterruptible(msecs_to_jiffies(10));
        spin_lock_irq(&port->lock);
        count = port->xmit_cnt;
        spin_unlock_irq(&port->lock);
    }

    if (flush) {
        spin_lock_irq(&port->lock);
        port->xmit_cnt = 0;
        spin_unlock_irq(&port->lock);
    }

    spin_lock_irq(&port->lock);
    if (!port->disconnecting) {
        baud_rate = port->baud_rate;
        if (baud_rate != 0) {
            timeout_jiffies = ((1000 * port->xmit_cnt * 8) / baud_rate) * HZ;
            if (timeout_jiffies > 0)
                schedule_timeout_uninterruptible(timeout_jiffies);
        }
    }
    spin_unlock_irq(&port->lock);
}
